"""Generate fixtures."""

import os
import json
import numpy as np
from sklearn.linear_model import SGDRegressor, SGDClassifier

# For reproducibility:
np.random.seed(1234)

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)

# Map scikit-learn penalty arguments to stdlib penalty names:
penalties = {
    None: "none",
    "l2": "l2",
    "l1": "l1",
    "elasticnet": "elasticnet"
}

# Map scikit-learn loss arguments to stdlib loss function names:
losses = {
    "squared_error": "squared-error",
    "huber": "huber",
    "epsilon_insensitive": "epsilon-insensitive",
    "squared_epsilon_insensitive": "squared-epsilon-insensitive",
    "hinge": "hinge",
    "squared_hinge": "squared-hinge",
    "perceptron": "perceptron",
    "modified_huber": "modified-huber",
    "log_loss": "log"
}

# Loss functions which require binary targets:
classification = (
    "hinge",
    "squared_hinge",
    "perceptron",
    "modified_huber",
    "log_loss"
)


def gen(
        name: str,
        loss: str = "squared_epsilon_insensitive",
        penalty: str | None = "l2",
        alpha: float = 1.0e-4,
        l1_ratio: float = 0.15,
        learning_rate: str = "constant",
        eta0: float = 0.01,
        power_t: float = 0.25,
        epsilon: float = 0.1,
        max_iter: int = 5,
        fit_intercept: bool = True,
        n_samples: int = 20,
        n_features: int = 3
    ):
    """Generate fixture data and write to file.

    # Arguments

    * `name::str`: output filename
    * `loss::str`: loss function name
    * `penalty`: penalty name
    * `alpha`: regularization parameter
    * `l1_ratio`: elastic net mixing parameter
    * `learning_rate::str`: learning rate schedule
    * `eta0`: initial learning rate
    * `power_t`: exponent for the inverse scaling learning rate
    * `epsilon`: insensitivity parameter
    * `max_iter`: number of epochs
    * `fit_intercept`: boolean indicating whether to fit an intercept
    * `n_samples`: number of samples
    * `n_features`: number of features

    # Examples

    ``` python
    python> gen('./data.json', penalty='l2')
    ```
    """
    x = np.asarray(
        np.random.uniform( -2.0, 2.0, ( n_samples, n_features ) ),
        dtype=np.float64
    )
    beta = np.random.uniform( -1.0, 1.0, n_features )
    y = x @ beta + np.random.normal( 0.0, 0.1, n_samples )

    if loss in classification:
        y = np.where( y > 0.0, 1.0, -1.0 ) # binary classification

    y = np.asarray( y, dtype=np.float64 )

    # Generate initial coefficients:
    w = np.asarray(
        np.random.uniform( -0.05, 0.05, n_features ),
        dtype=np.float64
    )

    opts = {
        "loss": loss,
        "penalty": penalty,
        "alpha": alpha,
        "l1_ratio": l1_ratio,
        "fit_intercept": fit_intercept,
        "max_iter": max_iter,
        "learning_rate": learning_rate,
        "eta0": eta0,
        "power_t": power_t,
        "epsilon": epsilon,

        # Equivalence settings to make it perform similar to stdlib implementation:
        "tol": None,
        "shuffle": False,
        "early_stopping": False,
        "warm_start": False,
        "average": False,
        "random_state": 0
    }

    if loss in classification:
        model = SGDClassifier(class_weight=None, **opts)
        model.fit(x, y, coef_init=w.reshape(1, n_features).copy(),
            intercept_init=np.zeros(1, dtype=np.float64))
        expected = model.coef_.ravel() # returns 2D array as it supports multi-class classification
    else:
        model = SGDRegressor(**opts)
        model.fit(x, y, coef_init=w.copy(),
                intercept_init=np.zeros(1, dtype=np.float64))
        expected = model.coef_

    # Ensure that the convergence check did not terminate training early:
    assert model.n_iter_ == max_iter, (name, model.n_iter_, max_iter)

    intercept = 0.0
    expected_intercept = float(model.intercept_[0])

    data = {
        "M": n_samples,
        "N": n_features,
        "X": x.ravel().tolist(),
        "y": y.tolist(),
        "w": w.tolist() + [intercept],
        "workspace": [0.0] * n_features,
        "order": "row-major",
        "LDX": n_features,
        "penalty": penalties[penalty],
        "loss_function": losses[loss],
        "learning_rate": learning_rate,
        "lambda": alpha,
        "l1_ratio": l1_ratio,
        "eta0": eta0,
        "power_t": power_t,
        "epsilon": epsilon,
        "max_iter": max_iter,
        "fit_intercept": fit_intercept,
        "intercept": intercept,
        "expected_w": expected.tolist(),
        "expected_intercept": expected_intercept
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(DIR, name)

    # Create the output directory if it doesn't exist:
    os.makedirs(os.path.dirname(filepath), exist_ok=True)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w", encoding="utf-8") as outfile:
        json.dump(data, outfile)

    # Include trailing newline:
    with open(filepath, "a", encoding="utf-8") as outfile:
        outfile.write("\n")


def main():
    """Generate fixture data."""
    # Penalties:
    gen("./penalties/penalty_none.json", penalty=None, alpha=0.0)
    gen("./penalties/penalty_l2.json", penalty="l2")
    gen("./penalties/penalty_l1.json", penalty="l1")
    gen("./penalties/penalty_elasticnet.json", penalty="elasticnet")

    # Learning rate schedules:
    gen("./learning-rates/lr_constant.json", learning_rate="constant")
    gen("./learning-rates/lr_invscaling.json", learning_rate="invscaling")

    # Intercept handling:
    gen("no_intercept.json", fit_intercept=False)

    # Large insensitivity parameter (i.e., many zero gradients):
    gen("large_epsilon.json", loss="squared_epsilon_insensitive", epsilon=2.0)

    # Loss functions (regression):
    gen("./loss-functions/loss_squared_error.json", loss="squared_error")
    gen("./loss-functions/loss_epsilon_insensitive.json", loss="epsilon_insensitive")
    gen("./loss-functions/loss_squared_epsilon_insensitive.json",
        loss="squared_epsilon_insensitive")
    gen("./loss-functions/loss_huber.json", loss="huber")

    # Loss functions (binary classification, `y` in `{-1,+1}`):
    gen("./loss-functions/loss_hinge.json", loss="hinge")
    gen("./loss-functions/loss_squared_hinge.json", loss="squared_hinge")
    gen("./loss-functions/loss_perceptron.json", loss="perceptron")
    gen("./loss-functions/loss_modified_huber.json", loss="modified_huber")
    gen("./loss-functions/loss_log.json", loss="log_loss")

    # Larger number of features:
    gen("large_nfeatures.json", penalty="elasticnet", n_samples=30,
        n_features=8)

    # Multiple epochs:
    gen("many_epochs.json", max_iter=25)


if __name__ == "__main__":
    main()
